mapper.select:
SELECT notice_no ,notice_date ,notice_type ,FIND_CODENAME(notice_type) AS notice_type_name ,notice_title ,notice_content
FROM notice
WHERE notice_no = #{noticeNo}

mapper.insert:

	SELECT NVL(MAX(notice_no),0) + 1
	FROM notice

INSERT INTO notice(
			notice_no
			,class_id
			,notice_date
			,notice_type

				,notice_title

			,notice_content
		)
		VALUES(
			#{noticeNo}
			,#{classId}
			,sysdate
			,#{noticeType}

				,#{noticeTitle}

			,#{noticeContent}
		)

mapper.update:
UPDATE notice


			notice_title = #{noticeTitle},


			notice_content = #{noticeContent}


